import sys

"""
To make the scripts compatible with both py 2 and 3 versions, string decode and encode operations
will be called in when str has to be utf-8 encoded.
"""


def decode_str(dec_string, decode_as='utf-8'):
    if sys.version_info[0] >= 3:
        if isinstance(dec_string, bytes):
            return dec_string.decode(decode_as)
    return dec_string


def encode_str(en_string, encode_as='utf-8'):
    if sys.version_info[0] >= 3:
        if isinstance(en_string, str):
            return en_string.encode(encode_as)
    return en_string
